<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, clearAuth, initializeAuth } from '../api'
const route = useRoute(); const router = useRouter(); const token = ref(''); const username = ref(''); const nickname = ref(''); const password = ref(''); const busy = ref(false); const error = ref(''); const valid = ref(false); const checking = ref(true)
onMounted(async () => { token.value = typeof route.query.token === 'string' ? route.query.token : ''; if (!token.value) { error.value = '邀请链接缺少令牌'; checking.value = false; return }; try { await api(`/auth/invitations/${encodeURIComponent(token.value)}`); valid.value = true } catch (e) { error.value = (e as Error).message } finally { checking.value = false } })
async function submit() { error.value = ''; if (password.value.length < 10) { error.value = '密码至少需要 10 个字符'; return }; busy.value = true; try { await api('/auth/register', { method: 'POST', body: JSON.stringify({ token: token.value, username: username.value, nickname: nickname.value, password: password.value, remember: true, device_name: navigator.userAgent }) }); await clearAuth(); await initializeAuth(true); router.replace('/ideas') } catch (e) { error.value = (e as Error).message } finally { busy.value = false } }
</script>
<template><main class="auth-page"><form class="auth-card" @submit.prevent="submit"><div class="auth-brand">COM · ItemGather</div><h1>接受邀请</h1><p v-if="checking" class="muted">正在检查邀请…</p><template v-if="valid"><div class="field"><label for="username">用户名</label><input id="username" v-model="username" minlength="2" maxlength="50" autocomplete="username" required /></div><div class="field"><label for="nickname">显示昵称</label><input id="nickname" v-model="nickname" maxlength="80" autocomplete="nickname" required /></div><div class="field"><label for="password">密码</label><input id="password" v-model="password" type="password" minlength="10" autocomplete="new-password" required /><small>至少 10 个字符，使用 Argon2id 安全保存。</small></div></template><p v-if="error" class="error-text">{{ error }}</p><button v-if="valid" class="primary" :disabled="busy">{{ busy ? '创建中…' : '创建账号并登录' }}</button><RouterLink v-if="!valid && !checking" to="/login">返回登录</RouterLink></form></main></template>
